class FactoryStateMachine:

    def __init__(self):

        self.machine_state = "IDLE"

    def update(self, vision_sensor):

        if vision_sensor:

            self.machine_state = "OBJECT_DETECTED"

        else:

            self.machine_state = "RUNNING"

    def get_status(self):

        return {

            "machine_state": self.machine_state
        }

import time


class EventManager:

    def __init__(self):

        self.events = []

    def add_event(self, event_type, message):

        event = {

            "time": time.strftime("%H:%M:%S"),

            "type": event_type,

            "message": message
        }

        self.events.append(event)

        print(f"[EVENT] {event}")

    def get_recent_events(self, limit=20):

        return self.events[-limit:]

from pymodbus.client import ModbusTcpClient


class FactoryModbusClient:

    def __init__(self, host, port):

        self.client = ModbusTcpClient(
            host=host,
            port=port
        )

    def connect(self):

        return self.client.connect()

    def read_input(self, address):

        result = self.client.read_discrete_inputs(
            address,
            count=1
        )

        if result.isError():

            return False

        return result.bits[0]

    def write_coil(self, address, value):

        self.client.write_coil(
            address,
            value
        )

    def write_register(self, address, value):

        # 有符号转无符号（Modbus保持寄存器为无符号16位）
        value = int(value)
        if value < 0:
            value = 65536 + value

        self.client.write_register(
            address,
            value
        )

    def close(self):

        self.client.close()

import time


class FactoryExecutor:

    def __init__(self, modbus, config, line_id=1):

        self.modbus = modbus
        self.config = config
        self.line_id = line_id

        # 根据产线号绑定对应的线圈地址
        if line_id == 1:
            self.conveyor_coil = config.CONVEYOR_COIL
            self.pusher_coil = config.PUSHER_COIL
        elif line_id == 2:
            self.conveyor_coil = config.CONVEYOR1_COIL
            self.pusher_coil = config.PUSHER1_COIL
        else:
            raise ValueError(f"不支持的产线编号: {line_id}")

    def start_conveyor(self):

        self.modbus.write_coil(
            self.conveyor_coil,
            True
        )

    def stop_conveyor(self):

        self.modbus.write_coil(
            self.conveyor_coil,
            False
        )

    def push_forward(self):

        self.modbus.write_coil(
            self.pusher_coil,
            True
        )

    def push_back(self):

        self.modbus.write_coil(
            self.pusher_coil,
            False
        )

    def push_object(self):

        self.push_forward()

        time.sleep(1)

        self.push_back()

import time


class PusherMonitor:

    def __init__(self):

        self.push_start_time = None

        self.push_timeout = False

        self.timeout_seconds = 5

    def start_push(self):

        self.push_start_time = time.time()

        self.push_timeout = False

    def update(self, pusher_back):

        if self.push_start_time is None:

            return

        # 推杆已返回
        if pusher_back:

            self.push_start_time = None

            self.push_timeout = False

            return

        duration = time.time() - self.push_start_time

        if duration > self.timeout_seconds:

            self.push_timeout = True

    def get_status(self):

        return {

            "push_timeout": self.push_timeout
        }

import time


class JamDetector:

    def __init__(self):

        self.block_start_time = None

        self.is_blocked = False

    def update(self, vision_sensor):

        if vision_sensor:

            if self.block_start_time is None:

                self.block_start_time = time.time()

            duration = time.time() - self.block_start_time

            if duration > 3:

                self.is_blocked = True

        else:

            self.block_start_time = None

            self.is_blocked = False

    def get_status(self):

        return {

            "is_blocked": self.is_blocked
        }

