from config import USE_MOCK_PLC

if USE_MOCK_PLC:
    from mock_plc import MockPLC as ModbusBackend
else:
    from pymodbus.client import ModbusTcpClient as ModbusBackend


class FactoryModbusClient:

    def __init__(self, host, port):

        if USE_MOCK_PLC:
            self.client = ModbusBackend()
        else:
            self.client = ModbusBackend(
                host=host,
                port=port
            )

    def connect(self):

        return self.client.connect()

        def read_input(self, address):

        if USE_MOCK_PLC:
            return self.client.read_input(address)

        result = self.client.read_discrete_inputs(
            address,
            count=1
        )

        if result.isError():

            return False

        return result.bits[0]

    def write_coil(self, address, value):

        self.client.write_coil(
            address,
            value
        )

    def write_register(self, address, value):

        if USE_MOCK_PLC:
            self.client.write_register(address, int(value))
            return

        # 有符号转无符号（Modbus保持寄存器为无符号16位）
        value = int(value)
        if value < 0:
            value = 65536 + value

        self.client.write_register(
            address,
            value
        )

    def close(self):

        self.client.close()

    # ==================== Mock 模式专用方法 ====================

    def set_input(self, address: int, value: bool):
        """设置模拟传感器的输入状态（仅在 USE_MOCK_PLC=True 时可用）"""
        if USE_MOCK_PLC:
            self.client.set_input(address, value)

    def set_inputs(self, **kwargs):
        """批量设置模拟传感器输入"""
        if USE_MOCK_PLC:
            self.client.set_inputs(**kwargs)

    def get_coil(self, address: int) -> bool:
        """读取线圈当前状态（Mock模式调试用）"""
        if USE_MOCK_PLC:
            return self.client.get_coil(address)
        return False

    def print_history(self, last_n=None):
        """打印操作历史（Mock模式调试用）"""
        if USE_MOCK_PLC:
            self.client.print_history(last_n)

    def clear_history(self):
        """清空操作历史（Mock模式调试用）"""
        if USE_MOCK_PLC:
            self.client.clear_history()

