# ==================== 测试状态机 ====================

class TestStateMachine(unittest.TestCase):
    """测试状态机状态转换"""

    def setUp(self):
        self.sm = StateMachine()

    def test_initial_state(self):
        self.assertEqual(self.sm.get_state(), "IDLE")

    def test_start_transition(self):
        result = self.sm.transition("START")
        self.assertTrue(result)
        self.assertEqual(self.sm.get_state(), "RUNNING")

    def test_pause_resume(self):
        self.sm.transition("START")
        self.sm.transition("PAUSE")
        self.assertEqual(self.sm.get_state(), "PAUSED")
        self.sm.transition("RESUME")
        self.assertEqual(self.sm.get_state(), "RUNNING")

    def test_stop_from_running(self):
        self.sm.transition("START")
        self.sm.transition("STOP")
        self.assertEqual(self.sm.get_state(), "STOPPED")

    def test_error_and_reset(self):
        self.sm.transition("START")
        self.sm.transition("ERROR")
        self.assertEqual(self.sm.get_state(), "ERROR")
        self.sm.transition("RESET")
        self.assertEqual(self.sm.get_state(), "IDLE")

    def test_invalid_transition(self):
        result = self.sm.transition("PAUSE")
        self.assertFalse(result)
        self.assertEqual(self.sm.get_state(), "IDLE")

    def test_estop(self):
        self.sm.transition("START")
        self.sm.transition("ESTOP")
        self.assertEqual(self.sm.get_state(), "ESTOP")


